-- 3. CHỦ TỊCH & HUẤN LUYỆN VIÊN VĨ ĐẠI (7 NHÂN VẬT LỊCH SỬ)
INSERT INTO club_leaders (id, full_name, role_type, tenure_years, major_trophies, win_rate_pct, image_url, legacy_vi, legacy_en) VALUES
('santiago-bernabeu', 'Santiago Bernabéu', 'President', '1943–1978', 32, NULL, '/images/players/santiago-bernabeu.jpg', 'Kiến trúc sư vĩ đại xây dựng thánh đường Nuevo Chamartín (nay là Santiago Bernabéu), chiêu mộ Di Stéfano và đồng sáng lập Cúp C1 châu Âu.', 'Visionary patriarch who built the Bernabéu stadium, signed Di Stéfano, and co-founded the European Cup.'),
('florentino-perez', 'Florentino Pérez', 'President', '2000–2006, 2009–2026+', 37, NULL, '/images/players/florentino-perez.jpg', 'Chủ tịch giàu thành tích nhất lịch sử bóng đá thế giới (37+ danh hiệu bóng đá, 7 Cúp C1), kiến tạo kỷ nguyên Galácticos và siêu sân vận động New Bernabéu.', 'Most decorated president in world football history (37+ football titles, 7 UCL crowns) and mastermind of the futuristic New Bernabéu.'),
('miguel-munoz', 'Miguel Muñoz', 'Player & Manager', '1959–1974 (HLV)', 14, 59.05, '/images/players/miguel-munoz.jpg', 'Người đầu tiên vô địch Cúp C1 cả trên tư cách Đội trưởng (1956, 1957, 1958) lẫn HLV trưởng (1960, 1966), dẫn dắt CLB 605 trận.', 'First man to win the European Cup as both captain and manager, leading Real Madrid for a record 605 matches.'),
('vicente-del-bosque', 'Vicente del Bosque', 'Player & Manager', '1999–2003 (HLV)', 7, 54.13, '/images/players/vicente-del-bosque.jpg', 'Nhà hiền triết dung hòa dàn sao Galácticos để mang về 2 chức vô địch Champions League (2000, 2002) và 2 La Liga.', 'Calm tactician who harmonized the Galácticos to win the 2000 and 2002 Champions League titles.'),
('carlo-ancelotti', 'Carlo Ancelotti', 'Manager', '2013–2015, 2021–2025', 15, 71.80, '/images/players/carlo-ancelotti.jpg', 'HLV giàu thành tích nhất lịch sử Real Madrid với 15 danh hiệu, bao gồm La Décima (2014), La Decimocuarta (2022) và La Decimoquinta (2024).', 'Most decorated manager in Real Madrid history with 15 trophies, including 3 Champions League crowns (2014, 2022, 2024).'),
('zinedine-zidane-manager', 'Zinedine Zidane (HLV)', 'Player & Manager', '2016–2018, 2019–2021', 11, 65.40, '/images/players/zinedine-zidane.jpg', 'HLV duy nhất trong lịch sử vô địch Champions League 3 mùa liên tiếp (2016, 2017, 2018) với tỷ lệ trung bình cứ 19 trận giành 1 danh hiệu.', 'Only manager in football history to win 3 consecutive UEFA Champions League titles (2016, 2017, 2018).'),
('jose-mourinho', 'José Mourinho', 'Manager', '2010–2013', 3, 71.91, '/images/players/jose-mourinho.jpg', 'Kiến trúc sư của "La Liga de los Récords" 2011/12 (100 điểm, 121 bàn thắng), đặt nền móng phản công thần tốc cho kỷ nguyên thống trị C1 sau đó.', 'Architect of the 2011/12 "Liga of Records" (100 points, 121 goals), forging the lethal counter-attacking DNA.');

-- 4. ĐẠI CHIẾN EL CLÁSICO (CẬP NHẬT TỚI TRẬN THẮNG 2–1 NGÀY 26/10/2026)
INSERT INTO el_clasico_matches (match_id, match_date, competition, venue, home_team, away_team, real_madrid_goals, barcelona_goals, key_scorers, highlight_vi, highlight_en) VALUES
('clasico-2026-10-26', '2026-10-26', 'La Liga 2026/27', 'Santiago Bernabéu', 'Real Madrid', 'FC Barcelona', 2, 1, 'Kylian Mbappé (24'', 78'')', 'Kylian Mbappé tỏa sáng rực rỡ với cú đúp đẳng cấp thế giới (phút 24 và phút 78 sau pha phối hợp tốc độ cùng #25 Yan Diomande & Bellingham) giúp Real Madrid đánh bại Barcelona 2–1 ngay tại thánh đường Bernabéu ngày 26/10/2026.', 'Kylian Mbappé delivered a world-class brace (24'' and 78'' following a supersonic transition with #25 Yan Diomande & Bellingham) as Real Madrid defeated Barcelona 2–1 at the Bernabéu on October 26, 2026.'),
('clasico-2024-04-21', '2024-04-21', 'La Liga 2023/24', 'Santiago Bernabéu', 'Real Madrid', 'FC Barcelona', 3, 2, 'Vinícius Jr (18''), Lucas Vázquez (73''), Jude Bellingham (90+1'')', 'Jude Bellingham ghi bàn ấn định chiến thắng 3–2 ở phút 90+1, chính thức định đoạt chức vô địch La Liga lần thứ 36.', 'Jude Bellingham struck a 90+1'' stoppage-time winner to seal a 3–2 comeback and Real Madrid''s 36th La Liga crown.'),
('clasico-2024-01-14', '2024-01-14', 'Siêu Cúp Tây Ban Nha 2024', 'Al-Awwal Park (Riyadh)', 'Real Madrid', 'FC Barcelona', 4, 1, 'Vinícius Jr (7'', 10'', 39''), Rodrygo (64'')', 'Vinícius Júnior lập cú hat-trick lịch sử chỉ trong 39 phút hiệp 1 giúp Real Madrid đè bẹp Barcelona 4–1 ở Chung kết Siêu Cúp.', 'Vinícius Júnior scored a sensational 39-minute first-half hat-trick to crush Barcelona 4–1 in the Supercopa Final.'),
('clasico-2023-04-05', '2023-04-05', 'Bán kết Cúp Nhà Vua 2022/23', 'Spotify Camp Nou', 'FC Barcelona', 'Real Madrid', 4, 0, 'Vinícius Jr (45+1''), Karim Benzema (50'', 58'', 80'')', 'Karim Benzema lập hat-trick hủy diệt 4–0 ngay tại Camp Nou để đưa Real Madrid tiến vào Chung kết và lên ngôi vô địch.', 'Karim Benzema netted a devastating hat-trick at Camp Nou as Real Madrid dismantled Barcelona 4–0.'),
('clasico-2012-04-21', '2012-04-21', 'La Liga 2011/12', 'Camp Nou', 'FC Barcelona', 'Real Madrid', 2, 1, 'Sami Khedira (17''), Cristiano Ronaldo (73'')', 'Khoảnh khắc "Calma, Calma" bất tử của Cristiano Ronaldo tại Camp Nou đưa đoàn quân Mourinho lên ngôi vô địch với kỷ lục 100 điểm.', 'Cristiano Ronaldo''s iconic "Calma, Calma" winner at Camp Nou that clinched the 100-point La Liga title.'),
('clasico-1995-01-07', '1995-01-07', 'La Liga 1994/95', 'Santiago Bernabéu', 'Real Madrid', 'FC Barcelona', 5, 0, 'Iván Zamorano (5'', 21'', 39''), Luis Enrique (68''), Amavisca (70'')', 'Iván Zamorano lập hat-trick ngay trong hiệp 1 giúp Real Madrid vùi dập Barcelona 5–0 trắng tại Bernabéu.', 'Iván Zamorano scored a first-half hat-trick in a historic 5–0 demolition at the Santiago Bernabéu.');
